import{_ as o,C as i,c as e,o as a,j as t,G as r,a0 as n,a as l}from"./chunks/framework.DKRgXLPU.js";const c=JSON.parse('{"title":"Testimonianze dei giocatori","description":"","frontmatter":{},"headers":[],"relativePath":"it/testimonials.md","filePath":"it/testimonials.md"}');const s=o({name:"it/testimonials.md"},[["render",function(o,c,s,u,m,p){const d=i("AdBanner"),h=i("AdInArticle");return a(),e("div",null,[c[0]||(c[0]=t("h1",{id:"testimonianze-dei-giocatori",tabindex:"-1"},[l("Testimonianze dei giocatori "),t("a",{class:"header-anchor",href:"#testimonianze-dei-giocatori","aria-label":'Permalink to "Testimonianze dei giocatori"'},"​")],-1)),r(d),c[1]||(c[1]=n('<p>Feedback reali da giocatori di pétanque d&#39;élite che hanno utilizzato le risorse della Pétanque Academy per migliorare il loro gioco mentale e le loro prestazioni in gara.</p><div class="tip custom-block"><p class="custom-block-title">Autentico e anonimo</p><p>Queste testimonianze rappresentano feedback autentici da parte di giocatori a vari livelli competitivi. Tutte le testimonianze sono anonime per proteggere la privacy dei giocatori e incoraggiare una condivisione onesta.</p></div><h2 id="concorrenti-regionali-e-nazionali" tabindex="-1">Concorrenti regionali e nazionali <a class="header-anchor" href="#concorrenti-regionali-e-nazionali" aria-label="Permalink to &quot;Concorrenti regionali e nazionali&quot;">​</a></h2><h3 id="quot-il-modello-di-coach-interiore-ha-cambiato-tutto-quot" tabindex="-1">&quot;Il modello di coach interiore ha cambiato tutto&quot; <a class="header-anchor" href="#quot-il-modello-di-coach-interiore-ha-cambiato-tutto-quot" aria-label="Permalink to &quot;&amp;quot;Il modello di coach interiore ha cambiato tutto&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Gioco a livello agonistico da 12 anni e pensavo di sapere tutto sulla pétanque. Ma ero il mio peggior nemico: mi criticavo costantemente dopo gli errori. Il modello &quot;Coach Interiore contro Critico Interiore&quot; del modulo &quot;Forza Mentale&quot; mi ha offerto un modo completamente diverso di parlare a me stesso durante la competizione.</em></p><p><em>Nel giro di due mesi, i miei compagni di squadra hanno notato la differenza. Ero più calmo, mi riprendevo più velocemente dai lanci sbagliati e mi divertivo di nuovo a gareggiare. Quest&#39;anno mi sono classificato terzo alle regionali: il mio miglior risultato di sempre.</em></p></blockquote><p><strong>— Campione regionale, Francia</strong></p><hr><h3 id="quot-finalmente-qualcuno-che-capisce-lo-sviluppo-delle-elite-quot" tabindex="-1">&quot;Finalmente qualcuno che capisce lo sviluppo delle élite&quot; <a class="header-anchor" href="#quot-finalmente-qualcuno-che-capisce-lo-sviluppo-delle-elite-quot" aria-label="Permalink to &quot;&amp;quot;Finalmente qualcuno che capisce lo sviluppo delle élite&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;La maggior parte degli allenamenti di pétanque si limita a &#39;allenarsi di più&#39; o &#39;lavorare sulla tecnica&#39;. Ma quando giochi da più di 15 anni, il problema non è questo. Il problema è riuscire ad acquisire la tecnica sotto pressione.</em></p><p><em>Il modulo Zone ha spiegato esattamente cosa stavo sperimentando: pensare troppo durante l&#39;esecuzione, rimanere in modalità analitica quando avrei dovuto essere nel flusso. Le tecniche pratiche per cambiare modalità sono state rivoluzionarie.</em></p><p><em>Questa è la prima risorsa che ho trovato che affronta effettivamente il gioco mentale a livello d&#39;élite.&quot;</em></p></blockquote><p><strong>— Giocatore della nazionale svedese</strong></p><hr><h3 id="quot-la-metodologia-del-workshop-ha-trasformato-il-nostro-club-quot" tabindex="-1">&quot;La metodologia del workshop ha trasformato il nostro club&quot; <a class="header-anchor" href="#quot-la-metodologia-del-workshop-ha-trasformato-il-nostro-club-quot" aria-label="Permalink to &quot;&amp;quot;La metodologia del workshop ha trasformato il nostro club&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Sono un allenatore di club e ho utilizzato la guida del Workshop per condurre una sessione di mental game con i nostri 8 migliori giocatori. Il quadro di sicurezza psicologica e il formato di discussione strutturato hanno dato vita a conversazioni che non avevamo mai avuto prima.</em></p><p><em>I giocatori hanno parlato apertamente dei loro critici interiori, delle loro risposte alla pressione, delle loro difficoltà di comunicazione di squadra. È stato incredibilmente efficace. Ora organizziamo queste sessioni mensilmente e la cultura di squadra è cambiata completamente.</em></p></blockquote><p><strong>— Allenatore del club, Germania</strong></p>',14)),r(h),c[2]||(c[2]=n('<hr><h2 id="giocatori-del-torneo" tabindex="-1">Giocatori del torneo <a class="header-anchor" href="#giocatori-del-torneo" aria-label="Permalink to &quot;Giocatori del torneo&quot;">​</a></h2><h3 id="quot-strumenti-pratici-che-funzionano-davvero-quot" tabindex="-1">&quot;Strumenti pratici che funzionano davvero&quot; <a class="header-anchor" href="#quot-strumenti-pratici-che-funzionano-davvero-quot" aria-label="Permalink to &quot;&amp;quot;Strumenti pratici che funzionano davvero&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ho letto libri di psicologia dello sport in passato, ma sono sempre troppo generici o troppo accademici. Il modello di obiettivo e il modello di diario della Pétanque Academy sono esattamente ciò di cui avevo bisogno: pratici, specifici per la pétanque e immediatamente utilizzabili.</em></p><p><em>Ho usato il modello di obiettivi e ho ottenuto un chiaro piano di sviluppo trimestrale in 30 minuti. Il modello di diario mi aiuta a monitorare non solo i risultati, ma anche le prestazioni mentali. Questi strumenti sono preziosi.</em></p></blockquote><p><strong>— Giocatore del torneo, Spagna</strong></p><hr><h3 id="quot-le-tecniche-di-consapevolezza-funzionano-in-competizione-quot" tabindex="-1">&quot;Le tecniche di consapevolezza funzionano in competizione&quot; <a class="header-anchor" href="#quot-le-tecniche-di-consapevolezza-funzionano-in-competizione-quot" aria-label="Permalink to &quot;&amp;quot;Le tecniche di consapevolezza funzionano in competizione&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ero scettico sulla mindfulness: mi sembrava troppo &#39;soft&#39; per gli sport agonistici. Ma le tecniche del modulo Mindfulness sono pratiche e specifiche. Il reset dei tre respiri, la scansione corporea per individuare le tensioni, gli esercizi di concentrazione sul momento presente.</em></p><p><em>Mi alleno 10 minuti ogni mattina e ora posso usare queste tecniche durante le gare. Quando sento che la pressione aumenta, ho gli strumenti per gestirla. Questo ha fatto una differenza tangibile nelle mie prestazioni.</em></p></blockquote><p><strong>— Giocatore del torneo, Paesi Bassi</strong></p><hr><h3 id="quot-comprendere-gli-stati-di-flusso-ha-sbloccato-il-mio-potenziale-quot" tabindex="-1">&quot;Comprendere gli stati di flusso ha sbloccato il mio potenziale&quot; <a class="header-anchor" href="#quot-comprendere-gli-stati-di-flusso-ha-sbloccato-il-mio-potenziale-quot" aria-label="Permalink to &quot;&amp;quot;Comprendere gli stati di flusso ha sbloccato il mio potenziale&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Avevo giocato partite in cui tutto funzionava alla perfezione, in cui non pensavo, giocavo solo alla perfezione. Ma non sapevo come accedere a quello stato in modo coerente. Il modulo Zone mi ha spiegato i principi scientifici alla base e mi ha fornito tecniche pratiche.</em></p><p><em>Imparare l&#39;ipofrontalità transitoria, comprendere il passaggio tra pianificazione ed esecuzione, mettere in pratica i trigger di flusso: queste conoscenze hanno reso quegli stati di massima prestazione molto più accessibili. Sto giocando la mia migliore partita a bocce di sempre.&quot;</em></p></blockquote><p><strong>— Giocatore regionale, Francia</strong></p><hr><h2 id="giocatori-di-squadra" tabindex="-1">Giocatori di squadra <a class="header-anchor" href="#giocatori-di-squadra" aria-label="Permalink to &quot;Giocatori di squadra&quot;">​</a></h2><h3 id="quot-e-diventato-il-compagno-di-squadra-che-tutti-vogliono-quot" tabindex="-1">&quot;È diventato il compagno di squadra che tutti vogliono&quot; <a class="header-anchor" href="#quot-e-diventato-il-compagno-di-squadra-che-tutti-vogliono-quot" aria-label="Permalink to &quot;&amp;quot;È diventato il compagno di squadra che tutti vogliono&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ero tecnicamente forte, ma avevo difficoltà nelle competizioni a squadre. Il modulo sulle dinamiche di squadra mi ha mostrato che essere un buon giocatore di squadra non significa solo fare buoni lanci, ma anche comunicare, avere fiducia e sicurezza psicologica.</em></p><p><em>Ho imparato a verbalizzare la fiducia, a comunicare chiaramente la strategia, a supportare i compagni di squadra dopo gli errori. Nel giro di pochi mesi, sono passato dall&#39;essere evitato all&#39;essere ricercato come partner. Quest&#39;anno ho vinto il campionato regionale a squadre.</em></p></blockquote><p><strong>— Giocatore di squadra, Italia</strong></p><hr><h3 id="quot-il-quadro-di-comunicazione-ha-salvato-la-nostra-partnership-quot" tabindex="-1">&quot;Il quadro di comunicazione ha salvato la nostra partnership&quot; <a class="header-anchor" href="#quot-il-quadro-di-comunicazione-ha-salvato-la-nostra-partnership-quot" aria-label="Permalink to &quot;&amp;quot;Il quadro di comunicazione ha salvato la nostra partnership&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Io e il mio compagno abituale eravamo in tensione: stili di gioco diversi, scarsa comunicazione, crescente frustrazione. Il modulo Team Player ci ha fornito uno schema per discuterne in modo costruttivo.</em></p><p><em>Abbiamo imparato a conoscere i modelli di comunicazione, a costruire la fiducia, a creare sicurezza psicologica. Abbiamo avuto conversazioni sincere utilizzando il formato del workshop. La nostra partnership è più forte che mai e i nostri risultati lo dimostrano.</em></p></blockquote><p><strong>— Squadra di doppio, Norvegia</strong></p><hr><h2 id="allenatori-e-formatori" tabindex="-1">Allenatori e Formatori <a class="header-anchor" href="#allenatori-e-formatori" aria-label="Permalink to &quot;Allenatori e Formatori&quot;">​</a></h2><h3 id="quot-ecco-come-si-presenta-l-39-elite-coaching-quot" tabindex="-1">&quot;Ecco come si presenta l&#39;Elite Coaching&quot; <a class="header-anchor" href="#quot-ecco-come-si-presenta-l-39-elite-coaching-quot" aria-label="Permalink to &quot;&amp;quot;Ecco come si presenta l&amp;#39;Elite Coaching&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ho allenato a bocce per 20 anni, concentrandomi principalmente sulla tecnica. Ma vedevo giocatori con una tecnica eccellente fallire sotto pressione. I moduli formativi mi hanno fornito la struttura per affrontare sistematicamente il gioco mentale.</em></p><p><em>La guida del Training Camp mi ha aiutato a strutturare un programma per il weekend che combinava lavoro tecnico e allenamento mentale. Il feedback dei giocatori è stato incredibile: hanno detto che è stato l&#39;allenamento più prezioso a cui abbiano mai partecipato.</em></p></blockquote><p><strong>— Allenatore, Francia</strong></p><hr><h3 id="quot-approccio-basato-sull-39-evidenza-all-39-allenamento-mentale-quot" tabindex="-1">&quot;Approccio basato sull&#39;evidenza all&#39;allenamento mentale&quot; <a class="header-anchor" href="#quot-approccio-basato-sull-39-evidenza-all-39-allenamento-mentale-quot" aria-label="Permalink to &quot;&amp;quot;Approccio basato sull&amp;#39;evidenza all&amp;#39;allenamento mentale&amp;quot;&quot;">​</a></h3><blockquote><p><em>&quot;Ciò che apprezzo di più è che non si tratta di semplici spunti motivazionali. Il contenuto si basa su ricerche psicologiche concrete: scienza dello stato di flusso, studi sulla consapevolezza, psicologia della performance. Ma è tradotto in tecniche pratiche e attuabili.</em></p><p><em>Utilizzo questi moduli come base per il coaching mentale con i miei giocatori d&#39;élite. L&#39;approccio strutturato, i framework chiari, gli esercizi pratici: questi sono contenuti di livello professionale.</em></p></blockquote><p><strong>— Psicologo dello sport e allenatore di bocce, Regno Unito</strong></p>',31)),r(d),c[3]||(c[3]=n('<hr><h2 id="temi-comuni" tabindex="-1">Temi comuni <a class="header-anchor" href="#temi-comuni" aria-label="Permalink to &quot;Temi comuni&quot;">​</a></h2><h3 id="cio-che-i-giocatori-apprezzano-di-piu" tabindex="-1">Ciò che i giocatori apprezzano di più <a class="header-anchor" href="#cio-che-i-giocatori-apprezzano-di-piu" aria-label="Permalink to &quot;Ciò che i giocatori apprezzano di più&quot;">​</a></h3><p>Sulla base del feedback, i giocatori sottolineano costantemente:</p><ol><li><strong>Contenuti pratici e attuabili</strong> - Non teoria, ma tecniche che puoi utilizzare oggi stesso</li><li><strong>Specifico per bocce</strong> - Progettato per le sfide uniche del bocce</li><li><strong>Focus di livello d&#39;élite</strong> - Affronta il gioco mentale, non la tecnica di base</li><li><strong>Quadri strutturati</strong> - Sistemi chiari, non consigli vaghi</li><li><strong>Gratuito e accessibile</strong> - Nessun paywall, disponibile per tutti</li></ol><h3 id="risultati-misurabili" tabindex="-1">Risultati misurabili <a class="header-anchor" href="#risultati-misurabili" aria-label="Permalink to &quot;Risultati misurabili&quot;">​</a></h3><p>I giocatori segnalano miglioramenti in:</p><ul><li>Risultati e performance della competizione</li><li>Coerenza sotto pressione</li><li>Tempo di recupero dopo gli errori</li><li>Comunicazione e dinamiche di squadra</li><li>Il piacere della competizione</li><li>Resilienza mentale</li></ul><h2 id="condividi-la-tua-esperienza" tabindex="-1">Condividi la tua esperienza <a class="header-anchor" href="#condividi-la-tua-esperienza" aria-label="Permalink to &quot;Condividi la tua esperienza&quot;">​</a></h2><p>Hai utilizzato le risorse della Pétanque Academy? Ci piacerebbe conoscere la tua esperienza.</p><p><strong>Invia la tua testimonianza via email a:</strong> <a href="mailto:patrik.wiik@gmail.com?subject=Testimonial" target="_blank" rel="noreferrer">patrik.wiik@gmail.com</a></p><p><strong>Include:</strong></p><ul><li>Il tuo livello di esperienza</li><li>Quali risorse hai utilizzato</li><li>Che impatto hanno avuto</li><li>Se possiamo condividere il tuo feedback (nome facoltativo)</li></ul><p>La tua storia potrebbe aiutare altri giocatori a scoprire queste risorse.</p><hr><h2 id="per-iniziare" tabindex="-1">Per iniziare <a class="header-anchor" href="#per-iniziare" aria-label="Permalink to &quot;Per iniziare&quot;">​</a></h2><p>Pronto a sviluppare la tua mentalità?</p><div class="tip custom-block"><p class="custom-block-title">Inizia qui</p><ul><li><strong>Nuovo nell&#39;allenamento mentale?</strong> → <a href="/it/education/the-zone/">The Zone</a></li><li><strong>Hai difficoltà con la pressione?</strong> → <a href="/it/educazione/forza-mentale/">Forza mentale</a></li><li><strong>Sfide di squadra?</strong> → <a href="/it/istruzione/giocatore-di-squadra/">Dinamiche di squadra</a></li><li><strong>Vuoi una struttura?</strong> → <a href="/it/goal-template">Modello obiettivo</a></li></ul></div>',18)),r(d)])}]]);export{c as __pageData,s as default};
